provider "aws" {
  region = "us-east-1"
}

resource "aws_security_group" "db_004" {
  name        = "pilot-rds-004"
  description = "Pilot RDS security group"

  ingress {
    description = "Public MySQL access for pilot scenario"
    from_port   = 3306
    to_port     = 3306
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    description = "Allow outbound traffic"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

